    private const string Prefix = "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/RarePriorThreePoint.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "RarePriorThreePoint", H("RarePriorThreePoint"), Blocks(
            Paragraph(Text("The normalized prior has rational weights at native depths 1, 2 and 3, whose source rates are 1/3, 2/5 and 3/8. Every legal short history uses the same selected prior. The exact same-history endpoint posterior identifies the zero-rare posterior, yielding a perturbation bound for the complete unbounded original record target. Long native histories activate the fixed monitor and concentrate on depth 3. Law error is the complete-record TV of historyGenerated and fullTarget. Configuration error averages that TV under the actual retained row before the supremum. phaseLawRisk and phaseConfRisk take the original PhaseHistory domain; shortLawRisk and shortConfRisk restrict its paid Reads to H. Pure actual rows prove equality, and all these ENNReal risks are bounded by 1 before toReal. Short-cap risk differs from the zero-rare risk by at most 1/1000. The full first-alpha cylinder gives phase-p risk at least 21/40. RarePriorAbsoluteRisk.all_history_absolute_risks bounds both absolute native zero-rare law and configuration risks on all original phase histories by 253/500 in p and 2/5 in beta. Original radius identification, Phi, charged full-machine realization and the uniform cutoff refutation U remain open.")),
            Node("every-short-history", "every_short_history", "every short history"),
            Node("every-short-complete-target", "every_short_complete_target", "every short complete target"),
            Node("long-history-concentration", "long_history_concentration", "long history concentration"),
            Node("long-endpoint-calibration", "long_endpoint_calibration", "long endpoint calibration"),
            Node("complete-record-risk-bridges", "complete_record_risk_bridges", "complete record risk bridges"))));

    private static DocumentBlock.Describe Node(string id, string name, string title) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Prefix + name), H(title),
            StatementSource.FromAuthor(Disp(Statement(name))), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The statement retains the complete original telescope and conditions."))), DescribeRole.Theorem);

